from pathlib import Path
root=Path(__file__).resolve().parents[1]
def edit(file,old,new):
 p=root/file;text=p.read_text(encoding='utf-8')
 if old not in text:raise Exception('Missing '+file+': '+old[:90])
 p.write_text(text.replace(old,new),encoding='utf-8')
def remove_line(file,prefix):
 p=root/file;lines=p.read_text(encoding='utf-8').splitlines();p.write_text('\n'.join(x for x in lines if not x.startswith(prefix))+'\n',encoding='utf-8')
