p=root/'app/hub.js';text=p.read_text(encoding='utf-8');needle="<div class=\"game-grid root-games\">${available.map(card).join('')}</div>";assert needle in text
text=text.replace(needle,"${preferredGames().length?`<section><h2>Your games</h2><div class=\"game-grid root-games\">${preferredGames().map(id=>state.games.find(g=>g.id===id)).filter(Boolean).map(card).join('')}</div></section><details class=\"other-games\"><summary>Other games</summary><div class=\"game-grid root-games\">${available.filter(g=>!preferredGames().includes(g.id)).map(card).join('')}</div></details>`:`<div class=\"game-grid root-games\">${available.map(card).join('')}</div>`}")
text=text.replace('<span class="library-count">${available.length} game spaces</span>','<button class="hub-button secondary" data-manage-games>Your main games</button>')
